'use client'
import { useRef, type CSSProperties } from 'react'
import { cellPaths, rng, useNearView } from '@/hooks/useCellBurst'

// The website's "endless data cells" (CellBurst.vue): the panel is a sheet of cells, and some cells on its border are
// redrawn smaller and smaller down to a vanishing point, each becoming a wedge of hairlines. The wedges are
// translucent, so where they overlap toward the centre they build up lighter. Each seed picks its own cells.
// `jumble` scatters it (a finer sheet, the vanishing point off centre, wedges from anywhere); `ledger` makes it a
// spreadsheet's (few columns, many thin rows, cells running in from the right); `strong` raises every layer for a red
// ground; `trace` sets the grid's own lines wiping away and drawing back in, each at its own pace. Drawn in a -1..1
// box stretched to the panel, so it fills it at any size. Put it in a `relative` panel; it is decorative.
export interface CellBurstProps {
  seed: number
  jumble?: boolean
  ledger?: boolean
  strong?: boolean
  trace?: boolean
}

// Hatch pitch in box units (about 3px), how near the centre the copies run, and how many cells light.
const PITCH = 0.012
const INNER = 0.04
const WEDGES = 12

type P = [number, number]

/** The convex hull of a cell's corners and the centre: the wedge its copies sweep out on their way in. */
function hull(points: P[]) {
  const pts = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1])
  const cross = (q: P, a: P, b: P) => (a[0] - q[0]) * (b[1] - q[1]) - (a[1] - q[1]) * (b[0] - q[0])
  const half = (list: P[]) => {
    const out: P[] = []
    for (const p of list) {
      while (out.length >= 2 && cross(out[out.length - 2]!, out[out.length - 1]!, p) <= 0) out.pop()
      out.push(p)
    }
    out.pop()
    return out
  }
  return [...half(pts), ...half([...pts].reverse())].map(p => p.join(',')).join(' ')
}

/** Everything the burst draws, from its props. */
function draw({ seed, jumble, ledger, strong, trace }: { seed: number, jumble: boolean, ledger: boolean, strong: boolean, trace: boolean }) {
  const o = strong ? { grid: 0.3, cross: 0.5, hull: 0.14, lines: 0.42 } : { grid: 0.18, cross: 0.3, hull: 0.07, lines: 0.16 }
  const COLS = ledger ? 5 : jumble ? 10 : 6
  const ROWS = ledger ? 16 : 6

  let grid = ''
  for (let i = 1; i < COLS; i++) grid += `M${-1 + (2 * i) / COLS} -1V1`
  for (let j = 1; j < ROWS; j++) grid += `M-1 ${-1 + (2 * j) / ROWS}H1`

  // The vanishing point: the centre; with `jumble` somewhere in the middle half; with `ledger` near the left edge.
  const vp: P = (() => {
    const rand = rng(seed * 7 + 3)
    if (ledger) return [-0.84, (rand() - 0.5) * 0.6]
    if (!jumble) return [0, 0]
    return [rand() - 0.5, rand() - 0.5]
  })()

  const wedges = (() => {
    const w = 2 / COLS
    const h = 2 / ROWS
    const [vx, vy] = vp
    const pool: P[] = []
    for (let i = 0; i < COLS; i++) {
      for (let j = 0; j < ROWS; j++) {
        if (ledger ? i >= COLS - 2 : jumble || i === 0 || j === 0 || i === COLS - 1 || j === ROWS - 1) pool.push([i, j])
      }
    }
    const rand = rng(seed)
    for (let n = pool.length - 1; n > 0; n--) {
      const m = Math.floor(rand() * (n + 1))
      ;[pool[n], pool[m]] = [pool[m]!, pool[n]!]
    }
    return pool.slice(0, WEDGES).map(([i, j]) => {
      const x0 = -1 + i * w
      const y0 = -1 + j * h
      return { hull: hull([[x0, y0], [x0 + w, y0], [x0 + w, y0 + h], [x0, y0 + h], [vx, vy]]), lines: cellPaths(x0 - vx, y0 - vy, w, h, PITCH, INNER).lines }
    })
  })()

  // With `trace`, the grid's lines and the cross through the vanishing point are drawn one by one in screen
  // percentages (no viewBox), so the stroke stays a hairline and the wipe runs in pixels.
  const traces = (() => {
    if (!trace) return []
    const rand = rng(seed * 13 + 1)
    const [vx, vy] = vp
    const out: { d: Record<'x1' | 'y1' | 'x2' | 'y2', string>, opacity: number, style: Record<'--dur' | '--delay', string> }[] = []
    const pct = (v: number) => `${((v + 1) * 50).toFixed(2)}%`
    const line = (x: number | null, y: number | null, opacity: number) => {
      const [a, b] = rand() < 0.5 ? ['100%', '0%'] : ['0%', '100%']
      const d = x !== null ? { x1: pct(x), y1: a, x2: pct(x), y2: b } : { x1: a, y1: pct(y!), x2: b, y2: pct(y!) }
      const dur = 6 + rand() * 8
      out.push({ d, opacity, style: { '--dur': `${dur.toFixed(2)}s`, '--delay': `${(-rand() * dur).toFixed(2)}s` } })
    }
    for (let i = 1; i < COLS; i++) line(-1 + (2 * i) / COLS, null, o.grid)
    for (let j = 1; j < ROWS; j++) line(null, -1 + (2 * j) / ROWS, o.grid)
    line(vx, null, o.cross)
    line(null, vy, o.cross)
    return out
  })()

  return { o, grid, vp, wedges, traces }
}

export function CellBurst({ seed, jumble = false, ledger = false, strong = false, trace = false }: CellBurstProps) {
  const root = useRef<SVGSVGElement | null>(null)
  const near = useNearView(root)
  const { o, grid, vp, wedges, traces } = draw({ seed, jumble, ledger, strong, trace })
  return (
    <>
      <style href="ds-cell-burst" precedence="ds">{css}</style>
      <svg data-ds="cell-burst" ref={root} className="pointer-events-none absolute inset-0 h-full w-full" viewBox="-1 -1 2 2" preserveAspectRatio="none" aria-hidden="true">
        {!traces.length && (
          <g fill="none" stroke="var(--ds-color-off-white)" strokeWidth="0.5" vectorEffect="non-scaling-stroke">
            <path d={grid} strokeOpacity={o.grid} vectorEffect="non-scaling-stroke" />
            <path d={`M${vp[0]} -1V1M-1 ${vp[1]}H1`} strokeOpacity={o.cross} vectorEffect="non-scaling-stroke" />
          </g>
        )}
        {(near ? wedges : []).map(wg => (
          <g key={wg.hull} className="ds-art-in">
            <polygon points={wg.hull} fill="var(--ds-color-off-white)" fillOpacity={o.hull} />
            <path d={wg.lines} transform={`translate(${vp[0]} ${vp[1]})`} fill="none" stroke="var(--ds-color-off-white)" strokeWidth="0.5" strokeOpacity={o.lines} vectorEffect="non-scaling-stroke" />
          </g>
        ))}
      </svg>
      {traces.length > 0 && (
        <svg data-ds="cell-burst" className="pointer-events-none absolute inset-0 h-full w-full" aria-hidden="true">
          <g fill="none" stroke="var(--ds-color-off-white)" strokeWidth="1">
            {traces.map((t, i) => <line key={i} {...t.d} pathLength={1} className="ds-cell-trace" strokeOpacity={t.opacity} style={t.style as CSSProperties} />)}
          </g>
        </svg>
      )}
    </>
  )
}

export default CellBurst

const css = `
.ds-art-in { animation: ds-art-in var(--ds-duration-art) var(--ds-easing-standard) both; }
@keyframes ds-art-in { from { opacity: 0; } }
/* Each line holds, wipes away from one end, then draws back in from the same end (home.css .cell-trace). */
.ds-cell-trace { stroke-dasharray: 1 1; stroke-dashoffset: 0; animation: ds-cell-trace var(--dur) var(--ds-easing-swap) infinite; animation-delay: var(--delay); }
@keyframes ds-cell-trace {
  0%, 62% { stroke-dashoffset: 0; }
  80% { stroke-dashoffset: -1; }
  80.01% { stroke-dashoffset: 1; }
  100% { stroke-dashoffset: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .ds-art-in, .ds-cell-trace { animation: none; }
}
`

// The website's grain (home.css .footer-grain): the brand texture tiled at 12% of the panel, laid over a dark or red
// ground at 30%. Decorative; put it first inside a `relative` panel.
export function Grain() {
  return (
    <>
      <style href="ds-grain" precedence="ds">{css}</style>
      <span data-ds="grain" aria-hidden="true" className="ds-grain pointer-events-none absolute inset-0 opacity-30" />
    </>
  )
}

export default Grain

const css = `
.ds-grain { background-image: url("/conare-ds/textures/grain.webp"); background-size: 12% auto; background-repeat: repeat; }
`

'use client'
import { useEffect, useState, type RefObject } from 'react'

// The "infinite cells" geometry behind the website's art (CellBurst, Burst): a level rectangle redrawn smaller and
// smaller as it recedes to a vanishing point at the origin, plus the seeded random source that keeps server and client
// drawing the same thing, and the two viewport helpers the art waits on.

/** A seeded random source (mulberry32), so server and client paths match. */
export function rng(seed: number) {
  let s = seed >>> 0
  return () => {
    s = (s + 0x6D2B79F5) >>> 0
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// Paths are joined with + rather than template strings: the registry's class check reads a path command followed by
// an interpolation as a class glued to one.
const r1 = (n: number) => Math.round(n * 10) / 10

/**
 * One cell: the face at (x0, y0), w by h, relative to the vanishing point, with its copies `pitch` apart on screen
 * until they reach `inner` of the face's distance. `fill` is the slab's ground, laid under it so it hides what lies
 * behind; `lines` is the hatch.
 */
export function cellPaths(x0: number, y0: number, w: number, h: number, pitch: number, inner: number) {
  // The ground: copies stepping back by a constant fraction, which overlap into one solid shape.
  const dist = Math.hypot(x0 + w / 2, y0 + h / 2)
  const step = 1 - pitch / dist
  let fill = ''
  for (let s = 1; s > inner; s *= step) fill += 'M' + r1(x0 * s) + ' ' + r1(y0 * s) + 'h' + r1(w * s) + 'v' + r1(h * s) + 'h' + r1(-w * s) + 'z'
  // The hatch: each edge redrawn as it recedes, at its own step, so its copies land `pitch` apart all the way in.
  let lines = ''
  const edges = [
    { c: y0, a: x0, len: w, level: true },
    { c: y0 + h, a: x0, len: w, level: true },
    { c: x0, a: y0, len: h, level: false },
    { c: x0 + w, a: y0, len: h, level: false },
  ]
  for (const e of edges) {
    const ds = pitch / Math.abs(e.c)
    for (let s = 1; s > inner; s -= ds) lines += e.level ? 'M' + r1(e.a * s) + ' ' + r1(e.c * s) + 'h' + r1(e.len * s) : 'M' + r1(e.c * s) + ' ' + r1(e.a * s) + 'v' + r1(e.len * s)
  }
  return { fill, lines }
}

/** Halftone squares: dots 4px apart in blocks of 3 by 3, each block one size, growing towards one top corner. */
export const HALFTONE_DOT = 4
export const HALFTONE_BLOCK = 3
const LEVELS = [0.25, 0.45, 0.7, 0.95]
const r2 = (n: number) => Math.round(n * 100) / 100

export function halftone(x: number, y: number, size: number, left: boolean, rand: () => number) {
  const n = Math.max(HALFTONE_BLOCK, Math.floor(size / HALFTONE_DOT))
  const blocks = Math.ceil(n / HALFTONE_BLOCK)
  const tone = Array.from({ length: blocks * blocks }, () => rand())
  let dots = ''
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      const across = left ? 1 - col / n : col / n
      const lean = (across + (1 - row / n)) / 2
      const t = tone[Math.floor(row / HALFTONE_BLOCK) * blocks + Math.floor(col / HALFTONE_BLOCK)]!
      const level = LEVELS[Math.min(LEVELS.length - 1, Math.floor((lean * 0.6 + t * 0.4) * LEVELS.length))]!
      const r = (HALFTONE_DOT / 2) * level
      const cx = x + (col + 0.5) * HALFTONE_DOT
      const cy = y + (row + 0.5) * HALFTONE_DOT
      dots += 'M' + r2(cx - r) + ' ' + r2(cy - r) + 'h' + r2(2 * r) + 'v' + r2(2 * r) + 'h' + r2(-2 * r) + 'z'
    }
  }
  const side = n * HALFTONE_DOT
  return { square: 'M' + r2(x) + ' ' + r2(y) + 'h' + side + 'v' + side + 'h' + -side + 'z', dots }
}

/** True once `el` comes within `margin` of the viewport, and from then on. Never on the server. */
export function useNearView(el: RefObject<Element | null>, margin = '400px') {
  const [near, setNear] = useState(false)
  useEffect(() => {
    if (!el.current || !('IntersectionObserver' in window)) {
      setNear(true)
      return
    }
    const io = new IntersectionObserver(([e]) => {
      if (!e?.isIntersecting) return
      setNear(true)
      io.disconnect()
    }, { rootMargin: margin })
    io.observe(el.current)
    return () => io.disconnect()
  }, []) // eslint-disable-line react-hooks/exhaustive-deps
  return near
}

/** True once `threshold` of `el` has been on screen, and from then on: a window that plays once. */
export function useSeen(el: RefObject<Element | null>, threshold = 0.2) {
  const [seen, setSeen] = useState(false)
  useEffect(() => {
    if (!el.current || !('IntersectionObserver' in window)) {
      setSeen(true)
      return
    }
    const io = new IntersectionObserver(([e]) => {
      if (!e?.isIntersecting) return
      setSeen(true)
      io.disconnect()
    }, { threshold })
    io.observe(el.current)
    return () => io.disconnect()
  }, []) // eslint-disable-line react-hooks/exhaustive-deps
  return seen
}
